<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { Clock3, Plus, Timer } from 'lucide-vue-next'
import Modal from '../components/Modal.vue'
import Pager from '../components/Pager.vue'
import DraftNotice from '../components/DraftNotice.vue'
import ConflictNotice from '../components/ConflictNotice.vue'
import HistoryPanel from '../components/HistoryPanel.vue'
import { useConflict,useDraft } from '../drafts'
import { api, durationLabel, isProjectReadOnly, localDate, messageOf, notify, projectName, query, softDelete, ui } from '../api'
import type { Page, Task, TimeEntry } from '../types'
interface Summary {total_minutes:number;by_day:Array<{date:string;minutes:number;over_eight_hours:boolean}>;by_project:Array<{project_id:string;project_name:string;minutes:number}>;by_task:Array<{task_id:string;project_id:string;task_name:string;minutes:number}>}
const props=defineProps<{revision:number}>();const emit=defineEmits<{changed:[]}>()
const entries=ref<TimeEntry[]>([]),summary=ref<Summary>(),offset=ref(0),total=ref(0),project=ref(''),taskFilter=ref(''),period=ref('day'),date=ref(localDate()),dateFrom=ref(localDate()),dateTo=ref(localDate()),loading=ref(false),error=ref(''),open=ref(false),saving=ref(false),formError=ref(''),editing=ref<TimeEntry>(),tasks=ref<Task[]>([]),filterTasks=ref<Task[]>([]);const limit=30
const form=reactive({project_id:'',task_id:'',work_date:localDate(),hours:0,minutes:30,note:''}),draft=useDraft(()=>`time_entries:${editing.value?.id||'new'}`,form,()=>open.value,()=>editing.value?.version),conflict=useConflict()
const minutes=computed(()=>Number(form.hours)*60+Number(form.minutes)),readonly=computed(()=>isProjectReadOnly(form.project_id)),leafTasks=computed(()=>tasks.value.filter(t=>!t.has_children&&t.status!=='canceled')),formTaskLoading=ref(false)
function setPeriod(){if(period.value==='custom')return;const day=new Date(date.value+'T00:00:00');if(Number.isNaN(day.valueOf()))return;if(period.value==='week'){const delta=(day.getDay()+6)%7;day.setDate(day.getDate()-delta)}dateFrom.value=formatDate(day);if(period.value==='week')day.setDate(day.getDate()+6);dateTo.value=formatDate(day)}
function formatDate(day:Date){return `${day.getFullYear()}-${String(day.getMonth()+1).padStart(2,'0')}-${String(day.getDate()).padStart(2,'0')}`}
function filters(){return{date_from:dateFrom.value,date_to:dateTo.value,project_id:project.value,task_id:taskFilter.value}}
async function load(){loading.value=true;error.value='';try{const [page,data]=await Promise.all([api<Page<TimeEntry>>(`/api/time-entries?${query({...filters(),limit,offset:offset.value})}`),api<Summary>(`/api/time-entries/summary?${query(filters())}`)]);entries.value=page.items;total.value=page.total;summary.value=data}catch(e){error.value=messageOf(e)}finally{loading.value=false}}
async function loadTasks(){if(!form.project_id){tasks.value=[];return}formTaskLoading.value=true;try{tasks.value=(await api<Page<Task>>(`/api/projects/${form.project_id}/tree`)).items}catch(e){formError.value=messageOf(e)}finally{formTaskLoading.value=false}}
async function loadFilterTasks(){filterTasks.value=[];if(!project.value)return;try{filterTasks.value=(await api<Page<Task>>(`/api/projects/${project.value}/tree`)).items.filter(t=>!t.has_children)}catch(e){error.value=messageOf(e)}}
function assign(entry?:TimeEntry){Object.assign(form,{project_id:entry?.project_id||project.value||ui.projects.find(p=>!isProjectReadOnly(p.id))?.id||'',task_id:entry?.task_id||'',work_date:entry?.work_date||date.value||localDate(),hours:entry?Math.floor(entry.minutes/60):0,minutes:entry?entry.minutes%60:30,note:entry?.note||''})}
async function edit(entry?:TimeEntry){if(open.value&&!draft.canLeave())return;editing.value=entry;assign(entry);formError.value='';conflict.clear();open.value=true;await loadTasks();if(entry)form.task_id=entry.task_id;await draft.reset()}
async function openEntity(id:string){try{await edit(await api<TimeEntry>(`/api/time-entries/${id}`))}catch(e){notify(messageOf(e),true)}}
async function save(){if(saving.value||readonly.value)return;if(!Number.isInteger(minutes.value)||minutes.value<1||minutes.value>1440){formError.value='工时必须为 1–1440 的整数分钟';return}saving.value=true;formError.value='';const payload={project_id:form.project_id,task_id:form.task_id,work_date:form.work_date,minutes:minutes.value,note:form.note,...(editing.value?{version:editing.value.version}:{})};try{const saved=await api<TimeEntry>(editing.value?`/api/time-entries/${editing.value.id}`:'/api/time-entries',{method:editing.value?'PATCH':'POST',body:JSON.stringify(payload)});draft.discard();open.value=false;notify(`工时已保存：${saved.work_date}，${durationLabel(saved.minutes)}`);emit('changed');await load()}catch(e){formError.value=messageOf(e);if(editing.value)await conflict.capture(e,`/api/time-entries/${editing.value.id}`,payload)}finally{saving.value=false}}
async function reloadConflict(){const remote=conflict.current.value?.remote as unknown as TimeEntry;if(!remote)return;draft.persist();editing.value=remote;assign(remote);conflict.clear();await loadTasks();form.task_id=remote.task_id;await draft.reset()}
async function remove(entry=editing.value){if(!entry||isProjectReadOnly(entry.project_id))return;try{if(await softDelete('time-entries',entry,`${entry.work_date} ${durationLabel(entry.minutes)}工时`)){draft.discard();open.value=false;emit('changed');await load()}}catch(e){open.value?formError.value=messageOf(e):error.value=messageOf(e)}}
function close(){if(!saving.value&&draft.canLeave())open.value=false}
function page(next:number){offset.value=next;void load()}
function apply(){offset.value=0;setPeriod();void load()}
onMounted(()=>{setPeriod();void load()});watch(()=>props.revision,load);watch(project,()=>{taskFilter.value='';void loadFilterTasks()});watch(()=>form.project_id,()=>{void loadTasks()});defineExpose({openEntity,canLeave:()=>!open.value||draft.canLeave()})
</script>
<template><div class="page-heading"><div><h1>工时</h1><p class="page-description">按实际投入记录分钟，按日、周查看项目与任务汇总。</p></div><button class="button primary" :disabled="!ui.projects.some(p=>!isProjectReadOnly(p.id))" @click="edit()"><Plus :size="17"/>记录工时</button></div><form class="filter-bar" @submit.prevent="apply"><select v-model="project" aria-label="工时所属项目"><option value="">全部项目</option><option v-for="p in ui.projects" :key="p.id" :value="p.id">{{p.name}}</option></select><select v-model="taskFilter" :disabled="!project" aria-label="工时所属任务"><option value="">全部任务与项目级工时</option><option v-for="task in filterTasks" :key="task.id" :value="task.id">{{task.wbs_code}} {{task.name}}</option></select><select v-model="period" class="period-filter" aria-label="工时统计周期"><option value="day">按日</option><option value="week">按周</option><option value="custom">自选日期</option></select><input v-if="period!=='custom'" v-model="date" type="date" aria-label="工时统计日期" class="filter-date" required/><template v-else><input v-model="dateFrom" type="date" aria-label="工时开始日期" class="filter-date" required/><input v-model="dateTo" type="date" aria-label="工时结束日期" :min="dateFrom" class="filter-date" required/></template><button type="submit" class="button subtle">查询</button></form><div v-if="error" class="error-banner" role="alert">{{error}}<button class="text-button" @click="load">重试</button></div><div v-if="summary" class="time-summary-strip"><Clock3 :size="21"/><div><strong>{{durationLabel(summary.total_minutes)}}</strong><span>{{dateFrom}} 至 {{dateTo}} · {{total}} 条工时记录</span></div><p>仅汇总实际工时条目，日志文字和预计工时不重复计入。</p></div><div class="time-layout"><section class="surface time-entry-list"><div class="section-heading"><h2>工时记录</h2><span class="muted">日累计最多 24 小时</span></div><p v-if="loading" class="loading-message">正在读取工时…</p><div v-else-if="!entries.length" class="empty-state"><Timer :size="36"/><h2>还没有这个时间范围的工时</h2><p>关联到项目或叶子任务，留下实际投入与工作说明。</p><button v-if="ui.projects.some(p=>!isProjectReadOnly(p.id))" class="button subtle small" @click="edit()">记录工时</button></div><div v-else class="table-scroll"><table><thead><tr><th>日期 / 项目任务</th><th>时长</th><th>工作说明</th><th class="right">操作</th></tr></thead><tbody><tr v-for="entry in entries" :key="entry.id"><td><button class="table-title" @click="edit(entry)">{{entry.work_date}}</button><small>{{entry.project_name||projectName(entry.project_id)}}</small><small>{{entry.task_name||(entry.task_id?'关联任务':'项目级工时')}}</small></td><td class="time-duration">{{durationLabel(entry.minutes)}}<small v-if="entry.minutes>480" class="overdue">单条超过 8 小时</small></td><td class="time-note">{{entry.note||'—'}}</td><td class="right"><button class="text-button" @click="edit(entry)">{{isProjectReadOnly(entry.project_id)?'查看':'编辑'}}</button></td></tr></tbody></table></div><Pager :offset="offset" :limit="limit" :total="total" @change="page"/></section><aside v-if="summary" class="time-summary-panel surface"><div class="section-heading"><h2>投入汇总</h2></div><details open><summary>按日期</summary><ul><li v-for="day in summary.by_day" :key="day.date"><span>{{day.date}}<small v-if="day.over_eight_hours" class="overdue">超过 8 小时，请核对</small></span><strong>{{durationLabel(day.minutes)}}</strong></li><li v-if="!summary.by_day.length" class="muted">暂无工时</li></ul></details><details open><summary>按项目</summary><ul><li v-for="item in summary.by_project" :key="item.project_id"><span>{{item.project_name}}</span><strong>{{durationLabel(item.minutes)}}</strong></li><li v-if="!summary.by_project.length" class="muted">暂无工时</li></ul></details><details><summary>按任务</summary><ul><li v-for="item in summary.by_task" :key="item.project_id+item.task_id"><span>{{item.task_name}}<small>{{projectName(item.project_id)}}</small></span><strong>{{durationLabel(item.minutes)}}</strong></li><li v-if="!summary.by_task.length" class="muted">暂无工时</li></ul></details></aside></div><Modal :open="open" :title="editing?'工时详情':'记录实际工时'" wide @close="close"><form class="modal-body" @submit.prevent="save"><DraftNotice :value="draft.available.value" :values="draft.values.value" :error="draft.storageError.value" :recovery="draft.recovery.value" @select="draft.select" @restore="draft.restore" @force="draft.restoreForced" @cancel-recovery="draft.clearRecovery" @discard="draft.discardAvailable"/><ConflictNotice :value="conflict.current.value" @keep="draft.persist();conflict.clear()" @reload="reloadConflict"/><fieldset :disabled="readonly||saving"><label>所属项目 <span class="required">*</span><select v-model="form.project_id" required @change="form.task_id=''"><option v-for="p in ui.projects.filter(p=>!isProjectReadOnly(p.id)||p.id===form.project_id)" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>关联叶子任务 <span class="muted">可留空，记为项目级工时</span><select v-model="form.task_id" :disabled="formTaskLoading"><option value="">项目级工时，不关联任务</option><option v-for="task in leafTasks" :key="task.id" :value="task.id">{{task.wbs_code}} {{task.name}}{{task.status==='done'?'（已完成）':''}}</option></select></label><label>工作日期 <span class="required">*</span><input v-model="form.work_date" type="date" required/></label><div class="form-row"><label>小时<input v-model.number="form.hours" type="number" min="0" max="24" step="1" required/></label><label>分钟<input v-model.number="form.minutes" type="number" min="0" max="59" step="1" required/></label></div><p class="duration-preview">本条 {{durationLabel(minutes)}}<span v-if="minutes>480" class="overdue">超过 8 小时，请核对</span></p><label>工作说明<textarea v-model="form.note" rows="3" maxlength="10000" placeholder="这段时间完成了什么"/></label></fieldset><p class="input-hint">以整数分钟保存，每条 1–1440 分钟；同一天所有项目累计不得超过 1440 分钟。已完成叶子任务仍可补记工时，结项与归档项目只读。</p><HistoryPanel v-if="editing" kind="time-entries" :id="editing.id" :revision="editing.version"/><p v-if="formError" class="form-error" role="alert">{{formError}}</p><div class="modal-footer"><span v-if="readonly" class="muted">项目已结项或归档，工时只读</span><button v-if="editing&&!readonly" type="button" class="button subtle small" @click="remove()">移入回收站</button><button v-if="!readonly" class="button primary" :disabled="saving||formTaskLoading">{{saving?'正在保存…':'保存工时'}}</button></div></form></Modal></template>
